import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BitInputStream_readBits_TriageGen1Test {

    private static final int MAXIMUM_CACHE_SIZE = 64; // Assuming this based on context





    @Test
    public void testReadBits_LittleEndian_Basic() throws IOException {
        // Data: 0x01, 0x02 -> Little Endian: 0x0201
        // Binary: 00000010 00000001
        byte[] data = {0x01, 0x02};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // Read 8 bits: should get 0x01
        assertEquals(1L, bis.readBits(8));
        // Read 8 bits: should get 0x02
        assertEquals(2L, bis.readBits(8));
    }












}

