import static org.junit.Assert.assertEquals;

public class BitInputStream_readBits_TriageGen1Test {

    private static final int MAXIMUM_CACHE_SIZE = 64; // Assuming this based on context







    @Test
    public void testReadBits_LittleEndian_CrossByte() throws IOException {
        // Data: 0x01, 0x02 (0x0201)
        byte[] data = {0x01, 0x02};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // Read 12 bits: 0x0201 & 0xFFF = 0x201 (513)
        // bitsCached becomes (0x0201 >>> 12) = 0
        assertEquals(513L, bis.readBits(12));
    }










}

