package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.ByteOrder;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BitInputStream_readBits_TriageGen1Test {

    private static final int MAXIMUM_CACHE_SIZE = 64; // Assuming this based on context















    @Test
    public void testReadBits_LargeCount_LittleEndian() throws IOException {
        // Test filling the cache to a large size
        byte[] data = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // Read 40 bits
        // bitsCached will be 0x0807060504030201
        // bitsOut = bitsCached & MASKS[40]
        long val = bis.readBits(40);
        // 40 bits = 5 bytes. In LE, first 5 bytes are 01 02 03 04 05
        // Value = 0x0504030201
        assertEquals(0x0504030201L, val);
    }


}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.ByteOrder;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BitInputStream_readBits_TriageGen1Test {

    private static final int MAXIMUM_CACHE_SIZE = 64; // Assuming this based on context

















    @Test
    public void testReadBits_ClearCache() throws IOException {
        byte[] data = {0x01, 0x02};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN);

        bis.readBits(4); // consumes some bits, bitsCachedSize becomes 4
        bis.clearBitCache();
        // After clear, bitsCachedSize is 0, bitsCached is 0
        // Next read should pull new bytes
        byte[] data2 = {0x0A};
        BitInputStream bis2 = new BitInputStream(new ByteArrayInputStream(data2), ByteOrder.BIG_ENDIAN);
        bis2.clearBitCache();
        assertEquals(10L, bis2.readBits(8));
    }
}
